// For each pushed order: ask Lightspeed which receipt it became and what state that receipt
// is in. DONE = the till took it and printed. NEW = the till never picked it up (Friturist
// #1002, 2026-09-04). WAITINGFORPAYMENT = items != payment. Both are silent from Srova's
// side because every step we own succeeded, so this is the only place they can be caught.
// SQL is built as a literal here (no queryReplacement - see poison-message lessons).
const items = $input.all();
function lit(v) { return v == null ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'"; }
const H = (t) => ({ Authorization: 'Bearer ' + t, Accept: 'application/json', 'User-Agent': 'SrovaWatchdog/1.0' });
const stmts = [];
let stuckCount = 0;
for (const it of items) {
  const o = it.json;
  let status = null, rid = null, err = null;
  try {
    const ord = await this.helpers.httpRequest({ url: `https://lightspeedapis.com/resto/rest/onlineordering/order/${o.ls_order_id}`, headers: H(o.access_token), json: true, timeout: 15000 });
    rid = ord && ord.receiptId;
    if (rid) {
      for (const d of [o.d0, o.d1]) {
        const r = await this.helpers.httpRequest({ url: `https://lightspeedapis.com/resto/rest/financial/receipt/?date=${d}&receiptId=${rid}`, headers: H(o.access_token), json: true, timeout: 15000 });
        const res = (r && r.results) || [];
        if (res.length) { status = res[0].status; break; }
      }
    }
  } catch (e) { err = 'ERR:' + String(e.message || e).slice(0, 100); }
  const stuck = status === 'NEW' || status === 'WAITINGFORPAYMENT';
  stmts.push(`INSERT INTO public.ls_receipt_watch (canonical_id, ls_order_id, ls_receipt_id, status, alerted) VALUES (${lit(o.canonical_id)}::uuid, ${lit(o.ls_order_id)}, ${rid ? Number(rid) : 'NULL'}, ${lit(status || err || 'UNKNOWN')}, ${stuck}) ON CONFLICT (canonical_id) DO UPDATE SET status = EXCLUDED.status, ls_receipt_id = COALESCE(EXCLUDED.ls_receipt_id, ls_receipt_watch.ls_receipt_id), checks = ls_receipt_watch.checks + 1, alerted = ls_receipt_watch.alerted OR EXCLUDED.alerted, checked_at = now()`);
  if (stuck) {
    stuckCount++;
    const msg = status === 'NEW'
      ? `Order ${o.external_ref} is in Lightspeed complete, but the till has NOT picked it up after ${o.age_min} min - it will not print by itself. Open it on the POS and print manually.`
      : `Order ${o.external_ref} is parked in Lightspeed as WAITING FOR PAYMENT (items do not match payment) - it will not print. Check it on the POS.`;
    const errJson = JSON.stringify({ code: 'LS_RECEIPT_' + status, stage: 'ls_receipt_watchdog', message: msg, ls_order_id: o.ls_order_id, ls_receipt_id: rid, ls_receipt_status: status, age_min: o.age_min, runbook: 'Order data is complete in Lightspeed - print it manually from the POS. If this repeats at one store, the iPad app is missing online-order pickups.' });
    stmts.push(`INSERT INTO public.dlq_alerts (queue_name, msg_id, canonical_order_id, external_ref, source, location_key, last_error, attempt_count) VALUES ('ls_receipt_stuck', ${Number(o.ls_order_id)}, ${lit(o.canonical_id)}::uuid, ${lit(o.external_ref)}, ${lit(o.source)}::public.order_source, ${lit(o.location_key)}, ${lit(errJson)}::jsonb, 1) ON CONFLICT (queue_name, msg_id) DO NOTHING`);
  }
}
// One statement only: chain every INSERT as a data-modifying CTE. Avoids relying on
// multi-statement support in the Postgres node.
const sql = stmts.length
  ? 'WITH ' + stmts.map((s, i) => `s${i} AS (${s} RETURNING 1)`).join(',\n') + '\nSELECT ' + stmts.length + ' AS statements'
  : 'SELECT 0 AS statements';
return [{ json: { sql, checked: items.length, stuck: stuckCount } }];
